# compute_stats.py
# Statistical analysis with a REAL vs SYNTHETIC split (supervisor feedback, Jul 2026).
#
# Why the split: the 89 synthetic templates were generated by Claude Sonnet 5 and use
# primitive types only, so blended "140" numbers are contaminated (they favour Claude,
# penalise models that use rich Accord types, and make extraction artificially easy).
# The REAL 51 templates are the benchmark that counts; the synthetic 89 are reported
# separately and never headlined.
#
# Reads results/{gemini,claude,gpt}/*.json (NO API calls). Produces, for each metric:
#   - real-51 and synthetic-89 headline % with Wilson 95% CIs, side by side
#   - pairwise significance ON THE REAL 51 (McNemar for binary, Wilcoxon for field tasks)
#   - iterations-to-valid (bootstrap CI) on the real 51
#   - a contamination summary: how much each model gains on the synthetic data
import json, math, os
import numpy as np
from scipy.stats import binomtest, wilcoxon
from categories import build_categories

MODELS = {"gemini": "Gemini 2.5 Flash", "claude": "Claude Haiku 4.5", "gpt": "GPT-5.4-mini"}
KEYS = list(MODELS)
PAIRS = [("gemini", "claude"), ("gemini", "gpt"), ("claude", "gpt")]
RNG = np.random.default_rng(0)

HERE = os.path.dirname(__file__)
SYN = set(os.listdir(os.path.join(HERE, "..", "synthetic-templates", "src")))

def template_name(item_id):
    return item_id.rsplit("-", 2)[0]

def subset_of(item_id):
    return "synthetic" if template_name(item_id) in SYN else "real"

def load(model, name):
    with open(os.path.join(HERE, "..", "results", model, f"{name}_results.json")) as f:
        return json.load(f)

def wilson(k, n, z=1.96):
    if n == 0:
        return (0.0, 0.0)
    p = k / n
    denom = 1 + z*z/n
    center = (p + z*z/(2*n)) / denom
    half = (z * math.sqrt(p*(1-p)/n + z*z/(4*n*n))) / denom
    return (max(0.0, center-half), min(1.0, center+half))

def pct(x): return f"{x*100:5.1f}%"
def verdict(p): return "SIGNIFICANT (p<0.05)" if p is not None and p < 0.05 else "not significant"

# ---- partition-aware aggregation ----
def agg_prop(model, name, num_key, den_key, want):
    """Sum num/den over items in the requested subset ('real'/'synthetic')."""
    k = n = 0
    for d in load(model, name)["details"]:
        if subset_of(d["id"]) != want:
            continue
        den = d[den_key] if isinstance(d[den_key], int) else len(d[den_key])
        k += d[num_key]; n += den
    return k, n

def bool_prop(model, name, key, want):
    k = n = 0
    for d in load(model, name)["details"]:
        if subset_of(d["id"]) != want:
            continue
        k += int(d[key]); n += 1
    return k, n

def per_template(model, name, num_key, den_key, want):
    """{id: proportion} for the requested subset (skips den==0)."""
    out = {}
    for d in load(model, name)["details"]:
        if subset_of(d["id"]) != want:
            continue
        den = d[den_key] if isinstance(d[den_key], int) else len(d[den_key])
        if den > 0:
            out[d["id"]] = d[num_key] / den
    return out

def per_item_bool(model, name, key, want):
    return {d["id"]: bool(d[key]) for d in load(model, name)["details"] if subset_of(d["id"]) == want}

# ---- tests ----
def mcnemar(a, b):
    ids = set(a) & set(b)
    nb = sum(1 for i in ids if a[i] and not b[i])
    nc = sum(1 for i in ids if b[i] and not a[i])
    if nb + nc == 0:
        return 1.0
    return binomtest(min(nb, nc), nb+nc, 0.5, alternative="two-sided").pvalue

def wilcoxon_pair(pa, pb):
    ids = sorted(set(pa) & set(pb))
    if not ids or all(pa[i] == pb[i] for i in ids):
        return None
    try:
        return wilcoxon([pa[i] for i in ids], [pb[i] for i in ids]).pvalue
    except ValueError:
        return None

def boot_mean_ci(vals, iters=10000):
    vals = np.array(vals, dtype=float)
    if len(vals) == 0:
        return (0.0, 0.0, 0.0)
    means = [RNG.choice(vals, size=len(vals), replace=True).mean() for _ in range(iters)]
    return (float(np.mean(vals)), float(np.percentile(means, 2.5)), float(np.percentile(means, 97.5)))

# metric registry: (label, file, num_key, den_key, kind)   kind: 'field' or 'bool'
FIELD_METRICS = [
    ("Classification accuracy", "classification", "correct", None, "bool"),
    ("Variable extraction",     "variable_extraction", "correct_fields", "total_fields", "field"),
    ("Type-mapping",            "type_mapping", "correct_fields", "total_fields", "field"),
    ("Model-gen coverage",      "model_generation", "types_covered", "gold_types", "field"),
]

commit = load(KEYS[0], "classification").get("template_library_commit", "unpinned")
n_real = sum(1 for d in load(KEYS[0], "classification")["details"] if subset_of(d["id"]) == "real")
n_syn = sum(1 for d in load(KEYS[0], "classification")["details"] if subset_of(d["id"]) == "synthetic")

print("=" * 72)
print("ACCORD BENCHMARK — STATISTICS (real vs synthetic split)")
print(f"Real templates: {n_real}   |   Synthetic: {n_syn}   |   library commit: {commit[:10]}")
print(f"Headline claims use the REAL {n_real} only. Synthetic is secondary/contaminated.")
print("=" * 72)

# ---------- 1. HEADLINE METRICS, real vs synthetic side by side ----------
print("\n--- 1. HEADLINE METRICS (real-51 vs synthetic-89, 95% Wilson CI) ---")
for label, fname, num, den, kind in FIELD_METRICS:
    print(f"\n{label}:")
    print(f"  {'model':<18} {'REAL-51':>24}    {'synthetic-89':>24}")
    for m in KEYS:
        if kind == "bool":
            kr, nr = bool_prop(m, fname, num, "real"); ks, ns = bool_prop(m, fname, num, "synthetic")
        else:
            kr, nr = agg_prop(m, fname, num, den, "real"); ks, ns = agg_prop(m, fname, num, den, "synthetic")
        lor, hir = wilson(kr, nr); los, his = wilson(ks, ns)
        print(f"  {MODELS[m]:<18} {pct(kr/nr)} [{pct(lor)},{pct(hir)}]   {pct(ks/ns)} [{pct(los)},{pct(his)}]")

# Classification also scored by CATEGORY: near-duplicate sibling templates (identical/near
# field sets, e.g. the 5 latedeliveryandpenalty variants) are collapsed, so the model is not
# marked wrong for picking an indistinguishable sibling. This is the fairer headline number.
cat_of = build_categories()
def cat_correct(d): return int(cat_of.get(d["model_answer"]) == cat_of.get(d["expected"]))
print("\nClassification by CATEGORY (near-duplicate siblings collapsed — fairer):")
for m in KEYS:
    det = load(m, "classification")["details"]
    rr = [d for d in det if subset_of(d["id"]) == "real"]
    ss = [d for d in det if subset_of(d["id"]) == "synthetic"]
    print(f"  {MODELS[m]:<18} REAL exact {pct(sum(d['correct'] for d in rr)/len(rr))} -> "
          f"cat {pct(sum(cat_correct(d) for d in rr)/len(rr))}   "
          f"synth exact {pct(sum(d['correct'] for d in ss)/len(ss))} -> "
          f"cat {pct(sum(cat_correct(d) for d in ss)/len(ss))}")

for label, fname, key in [("Raw validity (first pass)", "model_validity", "valid"),
                          ("Round-trip NAIVE reached valid", "model_roundtrip", "valid")]:
    print(f"\n{label}:")
    for m in KEYS:
        kr, nr = bool_prop(m, fname, key, "real"); ks, ns = bool_prop(m, fname, key, "synthetic")
        lor, hir = wilson(kr, nr); los, his = wilson(ks, ns)
        print(f"  {MODELS[m]:<18} REAL {pct(kr/nr)} [{pct(lor)},{pct(hir)}]   synth {pct(ks/ns)} [{pct(los)},{pct(his)}]")

print("\nRules-upfront first-pass valid:")
for m in KEYS:
    det = load(m, "model_rules")["details"]
    kr = sum(1 for d in det if subset_of(d["id"])=="real" and d["valid"] and d["tries"]==1)
    nr = sum(1 for d in det if subset_of(d["id"])=="real")
    ks = sum(1 for d in det if subset_of(d["id"])=="synthetic" and d["valid"] and d["tries"]==1)
    ns = sum(1 for d in det if subset_of(d["id"])=="synthetic")
    print(f"  {MODELS[m]:<18} REAL {pct(kr/nr)}   synth {pct(ks/ns)}")

# ---------- 2. PAIRWISE SIGNIFICANCE ON THE REAL 51 ----------
print(f"\n--- 2. PAIRWISE SIGNIFICANCE (REAL {n_real} ONLY) ---")

print("\nClassification (McNemar exact):")
cls = {m: per_item_bool(m, "classification", "correct", "real") for m in KEYS}
for a, b in PAIRS:
    p = mcnemar(cls[a], cls[b]); print(f"  {MODELS[a]:<18} vs {MODELS[b]:<18} p={p:.3f}  ({verdict(p)})")

for label, fname, num, den in [("Variable extraction", "variable_extraction", "correct_fields", "total_fields"),
                               ("Type-mapping", "type_mapping", "correct_fields", "total_fields"),
                               ("Model-gen coverage", "model_generation", "types_covered", "gold_types")]:
    print(f"\n{label} (Wilcoxon signed-rank):")
    P = {m: per_template(m, fname, num, den, "real") for m in KEYS}
    for a, b in PAIRS:
        p = wilcoxon_pair(P[a], P[b])
        txt = "all tied" if p is None else f"p={p:.4f}  ({verdict(p)})"
        print(f"  {MODELS[a]:<18} vs {MODELS[b]:<18} {txt}")

print("\nRound-trip NAIVE reached-valid (McNemar exact):")
rv = {m: per_item_bool(m, "model_roundtrip", "valid", "real") for m in KEYS}
for a, b in PAIRS:
    p = mcnemar(rv[a], rv[b]); print(f"  {MODELS[a]:<18} vs {MODELS[b]:<18} p={p:.4f}  ({verdict(p)})")

# ---------- 3. ITERATIONS-TO-VALID (real-51, bootstrap) ----------
print(f"\n--- 3. ITERATIONS-TO-VALID (REAL {n_real}, NAIVE feedback, bootstrap 95% CI) ---")
for m in KEYS:
    tries = [d["tries"] for d in load(m, "model_roundtrip")["details"]
             if subset_of(d["id"])=="real" and d["valid"]]
    mean, lo, hi = boot_mean_ci(tries)
    print(f"  {MODELS[m]:<18} mean {mean:.2f} tries  [{lo:.2f}, {hi:.2f}]  (n={len(tries)} valid)")

# ---------- 4. ONE-STAGE vs TWO-STAGE (real-51, with significance) ----------
print(f"\n--- 4. ONE- vs TWO-STAGE (REAL {n_real}, Wilcoxon) ---")
for m in KEYS:
    det = [d for d in load(m, "one_vs_two_stage")["details"] if subset_of(d["id"])=="real"]
    one = {d["id"]: d["one_stage_covered"]/d["gold_n"] for d in det if d["gold_n"]}
    two = {d["id"]: d["two_stage_covered"]/d["gold_n"] for d in det if d["gold_n"]}
    o = sum(one.values())/len(one); t = sum(two.values())/len(two)
    wins = sum(1 for i in one if one[i] > two[i]); losses = sum(1 for i in one if one[i] < two[i])
    p = wilcoxon_pair(one, two)
    ptxt = "tied" if p is None else f"p={p:.4f} ({verdict(p)})"
    print(f"  {MODELS[m]:<18} 1-stage {pct(o)}  2-stage {pct(t)}  (1 wins {wins}, 2 wins {losses})  {ptxt}")

# ---------- 5. CONTAMINATION SUMMARY ----------
print("\n--- 5. CONTAMINATION CHECK (synthetic minus real, per model) ---")
print("The synthetic generator was Claude Sonnet 5. If it contaminated the data, Claude")
print("should gain more on synthetic than the others. Positive delta = better on synthetic.\n")
for label, fname, num, den in [("Type-mapping", "type_mapping", "correct_fields", "total_fields"),
                               ("Coverage", "model_generation", "types_covered", "gold_types")]:
    print(f"{label}:")
    for m in KEYS:
        kr, nr = agg_prop(m, fname, num, den, "real"); ks, ns = agg_prop(m, fname, num, den, "synthetic")
        delta = (ks/ns - kr/nr) * 100
        print(f"  {MODELS[m]:<18} real {pct(kr/nr)} -> synth {pct(ks/ns)}   delta {delta:+5.1f} pts")
    print()

print("=" * 72)
print(f"Done. Headline on REAL {n_real}. Synthetic {n_syn} is secondary and contaminated.")
print("=" * 72)
